using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Compact side tip card (preRun bonuses / preFight moves): a small panel beside the action, never a centred
/// window. Pure reference holder for TipCard.prefab (generated by HelpScreenPrefabs); HelpTipsController fills it.
/// Rows are TipRow.prefab instances spawned under `rows`; long content is paged in the same space.
/// </summary>
public class TipCardView : MonoBehaviour
{
    public RectTransform root;
    public CanvasGroup group;
    [Tooltip("Fades between pages (the card itself stays).")]
    public CanvasGroup pageGroup;
    public TextMeshProUGUI titleText;
    public RectTransform rows;
    public TipRowView rowPrefab;
    public TextMeshProUGUI pageText;
    public Button moreInfoButton;
    public TextMeshProUGUI moreInfoLabel;
    public TextMeshProUGUI pauseHintText;
}
